package cn.mop.api;
import cn.mop.domain.*;
import cn.mop.domain.contact.*;
import cn.mop.domain.contact.ContactImportRepository.*;
import cn.mop.domain.contact.CustomerContactRepository.Access;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.*;
import org.junit.jupiter.api.*;
import org.mockito.ArgumentCaptor;
import org.springframework.mock.web.MockHttpServletRequest;
import java.nio.charset.StandardCharsets;
import java.time.*;
import java.util.*;
import java.util.function.Supplier;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
class ContactImportControllerTest {
    static final String ACTOR="66000000-0000-4000-8000-000000000001",TENANT="66000000-0000-4000-8000-000000000002",ID="66000000-0000-4000-8000-000000000003";
    PlatformRepository platform;ContactImportRepository repository;ContactImportController controller;ObjectMapper mapper=new ObjectMapper();
    @BeforeEach void setup(){platform=mock(PlatformRepository.class);repository=mock(ContactImportRepository.class);controller=new ContactImportController(platform,repository);member("padmin",true,1);when(platform.idempotentAuthorized(any(),any(),any(),any(),any(),anyLong(),any(),any())).thenAnswer(c->{((Runnable)c.getArgument(6)).run();return ((Supplier<?>)c.getArgument(7)).get();});when(repository.accept(any(),any())).thenReturn(job());}
    void member(String role,boolean active,long version){when(platform.membership(ACTOR,TENANT)).thenReturn(Optional.of(new Membership(ACTOR,TENANT,role,version,active)));}
    Access access(){return new Access(ACTOR,TENANT,1,"import-test");}
    Job job(){var now=Instant.parse("2026-10-03T19:00:00.123Z");return new Job(ID,TENANT,ACTOR,1,"a".repeat(64),ContactImportJobState.queued(1,now),1,now,now,List.of());}
    MockHttpServletRequest request(String method,String body){var r=new MockHttpServletRequest(method,"/api/v1/contact-imports");r.setUserPrincipal(()->ACTOR);r.getSession().setAttribute("mop.tenant_id",TENANT);r.setAttribute("mop.trace_id","import-test");r.addHeader("Idempotency-Key","import-test-key");r.setContentType("application/json");r.setContent(body.getBytes(StandardCharsets.UTF_8));return r;}
    ObjectNode row(){var r=mapper.createObjectNode().put("name","synthetic").putNull("mobile").putNull("email").putNull("wecom_user_id").putNull("preferred_priorities").putNull("quiet_window").put("enabled",false);r.putArray("roles").add("REPORTER");return r;}
    ObjectNode input(JsonNode... rows){var n=mapper.createObjectNode().put("expected_version",0).put("mode","CREATE_ONLY").put("acknowledge_exact_duplicate_rows",false);var a=n.putArray("rows");for(var row:rows)a.add(row);return n;}
    Map<?,?> data(Object result){return (Map<?,?>)((Map<?,?>)result).get("data");}
    Map<?,?> accept(ObjectNode body){return data(controller.accept(request("POST",body.toString())));}
    @Test void acceptanceOnlyReturnsImmutablePendingReceiptAndUsesProtectedCurrentAuthorization(){assertEquals(Map.of("operation_id",ID,"status","PENDING"),accept(input(row())));verify(repository).authorizeAcceptance(access());verify(repository).accept(eq(access()),any());verify(repository,never()).process(any());}
    @Test void exactDuplicateRowsRequireExplicitAcknowledgmentButNeverMerge(){var body=input(row(),row());var failure=assertThrows(DomainException.class,()->accept(body));assertEquals(409,failure.status);assertEquals("CONTACT_IMPORT_DUPLICATE_ACK_REQUIRED",failure.code);verifyNoInteractions(repository);accept(body.put("acknowledge_exact_duplicate_rows",true));var captured=ArgumentCaptor.forClass(List.class);verify(repository).accept(eq(access()),captured.capture());assertEquals(2,captured.getValue().size());assertEquals(captured.getValue().get(0),captured.getValue().get(1));}
    @Test void oneInvalidRowRejectsWholeBatchWithoutPartialAcceptance(){for(JsonNode bad:List.of(NullNode.instance,row().put("enabled","true"),row().put("tenant_id",TENANT),row().put("id",ID))){assertEquals(400,assertThrows(DomainException.class,()->accept(input(row(),bad,row()))).status);}verifyNoInteractions(repository);}
    @Test void exactRootModeVersionAckAndBoundedRowsRequired(){for(String field:List.of("mode","expected_version","acknowledge_exact_duplicate_rows","rows")){var body=input(row());body.remove(field);assertEquals(400,assertThrows(DomainException.class,()->accept(body)).status);}for(var body:List.of(input(row()).put("mode","UPSERT"),input(row()).put("expected_version",1),input(row()).put("expected_version",0.0),input(row()).putNull("acknowledge_exact_duplicate_rows"),input(row()).put("tenant_id",TENANT),input(),input(Collections.nCopies(101,row()).toArray(JsonNode[]::new))))assertEquals(400,assertThrows(DomainException.class,()->accept(body)).status);verifyNoInteractions(repository);accept(input(Collections.nCopies(100,row()).toArray(JsonNode[]::new)).put("acknowledge_exact_duplicate_rows",true));}
    @Test void unknownAndDuplicateQueriesRejectedOnReadsAndWrites(){for(String method:List.of("GET","POST")){var r=request(method,input(row()).toString());r.addParameter("tenant_id",TENANT);assertEquals(400,assertThrows(DomainException.class,()->{if(method.equals("GET"))controller.list(r);else controller.accept(r);}).status);}var duplicate=request("GET","");duplicate.addParameter("page_size","10","15");assertThrows(DomainException.class,()->controller.list(duplicate));var detail=request("GET","");detail.addParameter("page_size","15");assertThrows(DomainException.class,()->controller.get(ID,detail));verifyNoInteractions(repository);}
    @Test void strictJsonAndIdempotencyKeyRequiredBeforeWrite(){for(String body:List.of("{} {}","{\"rows\":[],\"rows\":[]}","[[[[[[1]]]]]]"," ".repeat(524289))){assertEquals(400,assertThrows(DomainException.class,()->controller.accept(request("POST",body))).status);}var r=request("POST",input(row()).toString());r.removeHeader("Idempotency-Key");assertThrows(DomainException.class,()->controller.accept(r));verifyNoInteractions(repository);}
    @Test void onlyCurrentAdministratorsMayReadOrAcceptBeforeBodyParsing(){for(String role:List.of("padmin","tadmin")){member(role,true,1);accept(input(row()));}clearInvocations(repository);for(String role:List.of("msp","viewer","unexpected")){member(role,true,1);assertEquals(403,assertThrows(DomainException.class,()->controller.accept(request("POST","bad"))).status);assertEquals(403,assertThrows(DomainException.class,()->controller.list(request("GET",""))).status);}verifyNoInteractions(repository);}
    @Test void staleMembershipAndMalformedSessionFailClosed(){for(long version:List.of(0L,1L)){member("padmin",false,version);assertEquals(401,assertThrows(DomainException.class,()->accept(input(row()))).status);}member("padmin",true,0);assertEquals(401,assertThrows(DomainException.class,()->accept(input(row()))).status);var r=request("GET","");r.getSession().setAttribute("mop.tenant_id",42);assertEquals(401,assertThrows(DomainException.class,()->controller.list(r)).status);r.setUserPrincipal(null);assertEquals(401,assertThrows(DomainException.class,()->controller.list(r)).status);verifyNoInteractions(repository);}
    @Test void receiptReplayReauthorizesButDoesNotAcceptOrInspectCurrentWorkerState(){doAnswer(c->{((Runnable)c.getArgument(6)).run();return Map.of("operation_id",ID,"status","PENDING");}).when(platform).idempotentAuthorized(any(),any(),any(),any(),any(),anyLong(),any(),any());assertEquals("PENDING",accept(input(row())).get("status"));verify(repository).authorizeAcceptance(access());verify(repository,never()).accept(any(),any());verify(repository,never()).get(any(),any());}
    @Test void canonicalSetOrderSameHashButRowOrderAndExplicitAcknowledgmentAreDistinct(){var one=row();one.putArray("roles").add("TECHNICAL_CONTACT").add("REPORTER");one.putArray("preferred_priorities").add("P4").add("P1");var two=one.deepCopy();two.putArray("roles").add("REPORTER").add("TECHNICAL_CONTACT");two.putArray("preferred_priorities").add("P1").add("P4");accept(input(one,row()));accept(input(two,row()));accept(input(row(),two));accept(input(one,row()).put("acknowledge_exact_duplicate_rows",true));var hashes=ArgumentCaptor.forClass(String.class);verify(platform,times(4)).idempotentAuthorized(any(),any(),any(),any(),hashes.capture(),anyLong(),any(),any());var h=hashes.getAllValues();assertEquals(h.get(0),h.get(1));assertNotEquals(h.get(0),h.get(2));assertNotEquals(h.get(0),h.get(3));}
    @Test void boundedListOnlyContainsOwnMetadataAndPairedCursor(){when(repository.list(access(),16,null,null)).thenReturn(Collections.nCopies(16,job()));var d=data(controller.list(request("GET","")));assertEquals(15,((List<?>)d.get("items")).size());assertEquals(true,d.get("has_more"));assertEquals(ID,d.get("next_before_id"));var item=(Map<?,?>)((List<?>)d.get("items")).get(0);assertFalse(item.containsKey("results"));assertFalse(item.containsKey("payload_bytes"));assertFalse(item.containsKey("lease_owner"));assertNull(item.get("worker_liveness"));assertEquals(false,item.get("notification_dispatched"));for(String size:List.of("0","101","16","015")){var r=request("GET","");r.addParameter("page_size",size);assertThrows(DomainException.class,()->controller.list(r));}var unpaired=request("GET","");unpaired.addParameter("before_id",ID);assertThrows(DomainException.class,()->controller.list(unpaired));}
    @Test void detailResultsAreImmutableVersionOneLinksAndForeignJob404Propagates(){var q=job();var done=q.state().claim("worker",q.createdAt(),Duration.ofSeconds(30)).orElseThrow().succeed("worker",1,q.createdAt(),1);var completed=new Job(q.id(),q.tenantId(),q.createdBy(),1,q.inputSha256(),done,3,q.createdAt(),q.updatedAt(),List.of(new ResultLink(1,ACTOR,1)));when(repository.get(access(),ID)).thenReturn(completed);var d=data(controller.get(ID,request("GET","")));assertEquals("SUCCEEDED",d.get("status"));assertEquals(List.of(Map.of("row_number",1,"contact_id",ACTOR,"contact_version",1L)),d.get("results"));verify(platform,never()).idempotentAuthorized(any(),any(),any(),any(),any(),anyLong(),any(),any());when(repository.get(access(),ID)).thenThrow(new DomainException(404,"OBJECT_NOT_FOUND","missing"));assertEquals(404,assertThrows(DomainException.class,()->controller.get(ID,request("GET",""))).status);}
}
